// Service worker — the piece that lets the app open at all with zero
// signal. Without this, "offline" just means the browser's own network
// error page; nothing of ours ever runs.
//
// Deliberately hand-written rather than generated by next-pwa/Workbox: the
// list of files to cache isn't known ahead of time here (Next.js names its
// JS/CSS chunks with content hashes that change every build, and wiring up
// a build-time manifest injector is more moving parts than this app needs).
// Instead this caches opportunistically at runtime — whatever got fetched
// during a normal online visit is what's available offline afterward. In
// practice that means: load the dashboard once with signal, and everything
// it needed (the page shell, its JS/CSS, fonts, icons) is cached for the
// next time there's none.
//
// Scope, on purpose: this only ever caches same-origin, static-ish GET
// requests (pages, `_next/static/*`, fonts, icons, the manifest). It never
// touches Supabase requests — those carry auth and live data, and a stale
// cached API response pretending to be fresh is a much worse bug than no
// offline support at all. Caching the *data* for offline use is what
// src/lib/localCache.ts (IndexedDB) is for; this file only ever deals in
// the app shell.

const CACHE_VERSION = "v1";
const NAV_CACHE = `badminton-nav-${CACHE_VERSION}`;
const ASSET_CACHE = `badminton-assets-${CACHE_VERSION}`;
const CURRENT_CACHES = new Set([NAV_CACHE, ASSET_CACHE]);

// How long to wait for the network before falling back to whatever's
// cached — long enough for a slow connection to still win the race, short
// enough that a dead connection doesn't leave the tap hanging.
const NAV_TIMEOUT_MS = 4000;

self.addEventListener("install", () => {
  // Take over from any previous service worker immediately rather than
  // waiting for every open tab to close first — there's no meaningful
  // "old version still needs to finish its work" case in an app this size.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => !CURRENT_CACHES.has(name)).map((name) => caches.delete(name))
      );
      await self.clients.claim();
    })()
  );
});

function isSameOrigin(url) {
  return url.origin === self.location.origin;
}

/** Static-ish, safe-to-cache-and-reuse assets: build output, icons, fonts,
 * the manifest itself. Not API routes, not anything under /api. */
function isCacheableAsset(url) {
  if (!isSameOrigin(url)) return false;
  if (url.pathname.startsWith("/api/")) return false;
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/icons/") ||
    url.pathname === "/manifest.json" ||
    /\.(?:woff2?|ttf|otf|svg|png|ico)$/.test(url.pathname)
  );
}

async function networkFirstNavigation(request) {
  const cache = await caches.open(NAV_CACHE);
  try {
    const networkPromise = fetch(request);
    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error("nav-timeout")), NAV_TIMEOUT_MS)
    );
    const response = await Promise.race([networkPromise, timeoutPromise]);
    if (response && response.ok) {
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cached = await cache.match(request);
    if (cached) return cached;
    // Nothing cached for this route and the network's unreachable — let it
    // fail normally rather than pretending to have something we don't.
    throw new Error("offline-and-uncached");
  }
}

async function staleWhileRevalidateAsset(request) {
  const cache = await caches.open(ASSET_CACHE);
  const cached = await cache.match(request);
  const networkFetch = fetch(request)
    .then((response) => {
      if (response && response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);
  // Serve the cached copy immediately if there is one (fast, and works
  // offline); still kick off the network fetch in the background so the
  // cache stays fresh for next time.
  return cached ?? (await networkFetch) ?? Response.error();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (!isSameOrigin(url)) return; // Never intercept Supabase or other cross-origin calls.

  if (request.mode === "navigate") {
    event.respondWith(networkFirstNavigation(request));
    return;
  }

  if (isCacheableAsset(url)) {
    event.respondWith(staleWhileRevalidateAsset(request));
  }
  // Everything else (API routes, etc.) passes through untouched.
});
